#!/usr/bin/env python3
# admin-wide-align-v1 / customer-delete-staff-v1
#   iPad・パソコンで上の帯・下のタブ・＋を予約表の列にそろえる／お店の端末でも、手で入れたお客さまを消せる
# 何度流しても同じ。元のファイルが想定と違うときは何も変えずに止まる
import hashlib, zlib, base64, json, os, shutil, sys, time
FILES = json.loads('{"supabase/functions/booking/index.ts": {"old": "78d7cb9b7c85ddb1411f0388ae206430", "new": "222a9de2d7b70c9fb91c6c96bb7555a7", "data": ""}, "docs/admin/admin.js": {"old": "9e2a880b230139b80bb54140a82b0be7", "new": "be9dce34b4613fb18ad2879648551ef9", "data": ""}, "docs/admin/admin.css": {"old": "3af134a909b70942d9c4da1802b2b188", "new": "134f32ebdae0bd52b67a7599c86de12d", "data": ""}, "docs/admin/index.html": {"old": "76a2d63aa5c0a4630e76a26033b5e5a4", "new": "50c13240891405273661aed16dff6b42", "data": ""}, "tests/admin_test.ts": {"old": "20ff34df26f187b1c146d8468de6f881", "new": "ff866bcda1027d404bb63c0b820b6ea2", "data": ""}, "tests/device_test.ts": {"old": "7df0057a4f77d064a9a13bb39ca6d753", "new": "b8284b88edbd01865c8d415fdaf201d8", "data": ""}}')
os.chdir(os.path.dirname(os.path.abspath(__file__)))
md5 = lambda b: hashlib.md5(b).hexdigest()
todo = []
for p, f in FILES.items():
    cur = md5(open(p, "rb").read()) if os.path.exists(p) else None
    if cur == f["new"]: print("済み", p); continue
    if cur != f["old"]: print("止めました：", p, "が想定と違います（", cur, "）。何も変えていません"); sys.exit(1)
    todo.append(p)
ts = time.strftime("%Y%m%d%H%M%S")
for p in todo:
    if os.path.exists(p): shutil.copy2(p, p + ".bak_" + ts)
    b = zlib.decompress(base64.b64decode(FILES[p]["data"]))
    assert md5(b) == FILES[p]["new"]
    open(p, "wb").write(b); print("更新" if FILES[p]["old"] else "追加", p)
print("lifeplus-admin-v4 OK")
